-- 初期データ投入用SQLスクリプト
-- このスクリプトは、データベースのテーブル作成と初期データ投入を行います
-- 
-- PasswordHashの値は、"password"という文字列をBCryptでハッシュ化した実際の値が設定されています
-- 全ユーザーのデフォルトパスワードは "password" です

-- 既存データを削除（オプション: 必要に応じてコメントアウト）
-- DELETE FROM "Users";
-- DELETE FROM "Companies";

-- Companiesテーブルを作成
CREATE TABLE IF NOT EXISTS "Companies" (
    "Id" INTEGER NOT NULL,
    "Name" VARCHAR(255) NOT NULL,
    "CreatedAt" TIMESTAMP NOT NULL,
    "UpdatedAt" TIMESTAMP NOT NULL,
    CONSTRAINT "PK_Companies" PRIMARY KEY ("Id")
);

-- Usersテーブルを作成（CompanyId・ManagerIdカラムを含む）
-- ManagerIdは直属の上司（同じUsersテーブルのId）を指す自己参照カラム。
-- 入社手続きの登録漏れがあった場合はNULLになる（GameDayシナリオ ステップ1の障害データ）。
CREATE TABLE IF NOT EXISTS "Users" (
    "Id" INTEGER NOT NULL,
    "Name" VARCHAR(255) NOT NULL,
    "Email" VARCHAR(255) NOT NULL,
    "PasswordHash" VARCHAR(255) NOT NULL,
    "Role" VARCHAR(50) NOT NULL,
    "Department" VARCHAR(255) NULL,
    "CompanyId" INTEGER NULL,
    "ManagerId" INTEGER NULL,
    "CreatedAt" TIMESTAMP NOT NULL,
    "UpdatedAt" TIMESTAMP NOT NULL,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Users_Companies_CompanyId" FOREIGN KEY ("CompanyId") REFERENCES "Companies" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_Users_Users_ManagerId" FOREIGN KEY ("ManagerId") REFERENCES "Users" ("Id") ON DELETE SET NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_Users_Email" ON "Users" ("Email");

